// #7c30a0f9 — TC-AD-01 (open ad page from search), TC-AD-02 (form validation, nothing is published)
import assert from 'node:assert/strict';
import { startDriver, byText, search, goTab, IS_IOS } from '../lib/session.js';

describe('Job ad page & publish form #7c30a0f9 @ios @android @prod-safe', function () {
  let d;
  before(async () => { d = await startDriver(); });
  after(async () => { if (d) await d.deleteSession(); });

  it('TC-AD-01: tapping an ad in job search opens "מודעת דרושים", publisher button opens the publisher', async () => {
    await search(d, 'עבודה', 'פועל כללי');
    const firstAdText = await byText(d, 'דרושים', true);   // any ad body containing "דרושים"
    await firstAdText.waitForDisplayed({ timeout: 20000 });
    await firstAdText.click();
    await (await byText(d, 'מודעת דרושים')).waitForDisplayed({ timeout: 15000 });
    await (await byText(d, 'דרושים:', true)).waitForDisplayed({ timeout: 5000 });
    await (await byText(d, 'פורסם על ידי')).waitForDisplayed({ timeout: 5000 });
    assert.equal(await (await byText(d, 'הסרת המודעה')).isExisting(), false, 'non-author must not see delete');
    await (await byText(d, 'לפרופיל המפרסם')).click();
    await (await byText(d, 'Joni workers rate')).waitForDisplayed({ timeout: 15000 });
  });

  it('TC-AD-02: amount validation and required city (form is never submitted successfully)', async () => {
    await goTab(d, 'פרסם');
    await (await byText(d, 'מודעת דרוש עובד/שירות')).click();
    await (await byText(d, 'פרסום מודעת דרושים')).waitForDisplayed({ timeout: 10000 });
    await (await byText(d, 'יומי')).click();
    const publish = async () => {
      const b = await byText(d, 'פרסם מודעה');
      await b.scrollIntoView?.().catch(() => {});
      await b.click();
    };
    await publish();
    await (await byText(d, 'הזינו סכום')).waitForDisplayed({ timeout: 5000 });
    const amount = IS_IOS ? (await d.$$('-ios class chain:**/XCUIElementTypeTextField')).at(-1)
                          : (await d.$$('android.widget.EditText')).at(-1);
    for (const v of ['0', '100001', '1.5', '-5']) {
      await amount.clearValue(); await amount.setValue(v);
      await publish();
      await (await byText(d, 'סכום בשקלים שלמים', true)).waitForDisplayed({ timeout: 5000 });
      await (await byText(d, 'פרסום מודעת דרושים')).waitForDisplayed({ timeout: 3000 });
    }
    await (await byText(d, '✕')).click();          // clear "מיקום העבודה"
    await amount.clearValue(); await amount.setValue('750');
    await publish();
    await (await byText(d, 'חובה למלא את השדה')).waitForDisplayed({ timeout: 5000 });
    await (await byText(d, 'פרסום מודעת דרושים')).waitForDisplayed({ timeout: 3000 }); // still on form — nothing published
  });
});
